<?php defined('_JEXEC') or die; $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); $items=array_map(static fn($v)=>(array)$v,array_values((array)$params->get('items',[]))); if(!$items)return; ?>
<section class="section container home-tabs-section"><span class="eyebrow home-tabs-eyebrow"><?= $e($params->get('eyebrow')) ?></span><div class="cards-grid home-tabs-grid"><?php foreach($items as $item): ?><a class="feature-card" href="<?= $e($item['url']??'') ?>"><div class="feature-icon" aria-hidden="true"><span class="vplo-section-icon vplo-section-icon-<?= $e($item['icon']??'school') ?>"></span></div><h3><?= $e($item['title']??'') ?></h3></a><?php endforeach; ?></div></section>
